INSERT INTO `hadiths` VALUES (1,'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ','The best among you are those who learn the Quran and teach it to others.','تم میں سے بہترین شخص وہ ہے جو قرآن سیکھے اور دوسروں کو سکھائے۔','Uthman ibn Affan (RA)','Sahih al-Bukhari 5027','Virtues of the Quran','quran','Sahih',1,'2026-10-21 04:34:22','2026-10-21 04:34:22'),(2,'اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ','Recite the Quran, for it will come as an intercessor for its reciters on the Day of Resurrection.','قرآن پڑھا کرو، کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کے لیے شفاعت کرے گا۔','Abu Umamah Al-Bahili (RA)','Sahih Muslim 804','Virtues of Reciting Quran','quran','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(3,'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ','Whoever takes a path upon which he seeks knowledge, Allah will make easy for him the path to Paradise.','جو شخص علم کی تلاش میں کسی راستے پر چلے، اللہ تعالیٰ اس کے لیے جنت کا راستہ آسان فرما دیتا ہے۔','Abu Hurairah (RA)','Sahih Muslim 2699','The Book of Knowledge','knowledge','Sahih',1,'2026-10-21 04:34:22','2026-10-21 04:34:22'),(4,'الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ','The one who is proficient in the recitation of the Quran will be with the honorable scribes (angels), and he who recites the Quran with difficulty, stammering, will have a double reward.','قرآن کا ماہر معزز اور نیک فرشتوں کے ساتھ ہوگا، اور جو اٹک اٹک کر تلاوت کرتا ہے اور اس پر مشقت ہوتی ہے اس کے لیے دوہرا اجر ہے۔','Aisha (RA)','Sahih al-Bukhari 4937','Virtues of the Quran','quran','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(5,'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى','Actions are judged by intentions, and every person will get what they intended.','اعمال کا دارومدار نیتوں پر ہے، اور ہر انسان کو وہی ملے گا جس کی اس نے نیت کی۔','Umar ibn al-Khattab (RA)','Sahih al-Bukhari 1','Revelation & Intentions','character','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(6,'إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ أَحَاسِنَكُمْ أَخْلاَقًا','The most beloved of you to me and the closest of you to my gathering on the Day of Resurrection are those of you with the best character.','قیامت کے دن تم میں سے مجھے سب سے زیادہ محبوب اور میرے سب سے قریب بیٹھنے والا وہ شخص ہوگا جس کے اخلاق سب سے اچھے ہوں۔','Jabir ibn Abdullah (RA)','Jami at-Tirmidhi 2018','Righteousness and Relations','character','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(7,'مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لَا أَقُولُ الم حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ وَلَامٌ حَرْفٌ وَمِيمٌ حَرْفٌ','Whoever recites a letter from the Book of Allah will receive one good deed for it, and that good deed is multiplied tenfold. I do not say that Alif-Lam-Mim is one letter, but Alif is a letter, Lam is a letter, and Mim is a letter.','جس نے اللہ کی کتاب کا ایک حرف پڑھا اس کے لیے ایک نیکی ہے، اور ایک نیکی کا بدلہ دس گنا ہے۔ میں یہ نہیں کہتا کہ الم ایک حرف ہے، بلکہ الف ایک حرف، لام ایک حرف اور میم ایک حرف ہے۔','Abdullah ibn Masud (RA)','Jami at-Tirmidhi 2910','Virtues of the Quran','quran','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(8,'عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ، إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ','How wonderful is the affair of the believer, for all of his affairs are good! If good comes to him, he is thankful, and that is good for him. If adversity strikes him, he is patient, and that is good for him.','مومن کا معاملہ بھی خوب ہے! اس کے ہر کام میں خیر ہے۔ اگر اسے خوشی ملے تو وہ شکر کرتا ہے جو اس کے لیے بہتر ہے، اور اگر تکلیف پہنچے تو وہ صبر کرتا ہے جو اس کے لیے خیر ہے۔','Suhayb ibn Sinan (RA)','Sahih Muslim 2999','Patience and Gratitude','patience','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(9,'أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ تَعَالَى أَدْوَمُهَا وَإِنْ قَلَّ','The deeds most beloved to Allah are those done regularly, even if they are few.','اللہ تعالیٰ کو سب سے زیادہ پسندیدہ وہ عمل ہے جو ہمیشہ کیا جائے، اگرچہ تھوڑا ہی ہو۔','Aisha (RA)','Sahih Muslim 783','Steadfastness in Worship','prayer','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(10,'مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرُبَاتِ يَوْمِ الْقِيَامَةِ','Whoever fulfills the need of his brother, Allah will fulfill his need; and whoever relieves a Muslim of a distress, Allah will relieve him of a distress on the Day of Resurrection.','جو اپنے مسلمان بھائی کی ضرورت پوری کرے گا، اللہ اس کی ضرورت پوری فرمائے گا، اور جو کسی کی مصیبت دور کرے گا، اللہ قیامت کے دن اس کی مصیبت دور فرمائے گا۔','Abdullah ibn Umar (RA)','Sahih al-Bukhari 2442','Brotherhood and Support','kindness','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(11,'الدُّعَاءُ هُوَ الْعِبَادَةُ','Supplication (Dua) is the very essence of worship.','دعا ہی اصل عبادت ہے۔','An-Nu\'man ibn Bashir (RA)','Sunan Abi Dawud 1479','Supplication','prayer','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(12,'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ','Smiling in the face of your brother is an act of charity for you.','اپنے بھائی کے سامنے مسکرا دینا بھی تمہارے لیے صدقہ ہے۔','Abu Dharr al-Ghifari (RA)','Jami at-Tirmidhi 1956','Righteousness and Charity','kindness','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(13,'يُقَالُ لِصَاحِبِ الْقُرْآنِ: اقْرَأْ وَارْتَقِ وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا، فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَؤُهَا','It will be said to the companion of the Quran: Recite and ascend, and recite carefully as you recited in the world, for your status will be at the last verse you recite.','صاحبِ قرآن سے کہا جائے گا: پڑھتا جا اور جنت کے درجات چڑھتا جا، اور ترتیل سے پڑھ جیسا تو دنیا میں پڑھتا تھا، تیرا درجہ وہی ہے جہاں تیری آخری آیت ختم ہوگی۔','Abdullah ibn Amr (RA)','Sunan Abi Dawud 1464','Virtues of the Quran','quran','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(14,'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ','The strong person is not the one who overcomes people in wrestling; rather, the strong person is the one who controls himself when angry.','طاقتور وہ نہیں جو پہلوانی میں پچھاڑ دے، بلکہ اصل طاقتور وہ ہے جو غصے کے وقت اپنے نفس پر قابو رکھے۔','Abu Hurairah (RA)','Sahih al-Bukhari 6114','Good Manners & Self Control','character','Sahih',1,'2026-10-21 04:34:22','2026-10-21 05:07:48'),(15,'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ','Whomever Allah desires good for, He grants him deep understanding of the religion.','اللہ تعالیٰ جس کے ساتھ بھلائی کا ارادہ فرماتا ہے، اسے دین کی گہری سمجھ عطا فرما دیتا ہے۔','Mu\'awiyah (RA)','Sahih al-Bukhari 71','Knowledge','knowledge','Sahih',1,'2026-10-21 04:34:22','2026-10-21 04:34:22'),(16,'مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الأُتْرُجَّةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا طَيِّبٌ','The example of a believer who recites the Quran is like that of a citron (fragrant citrus): its smell is delightful and its taste is delicious.','قرآن پڑھنے والے مومن کی مثال سنگترے جیسی ہے، جس کی خوشبو بھی عمدہ ہے اور ذائقہ بھی میٹھا ہے۔','Abu Musa al-Ashari (RA)','Sahih al-Bukhari 5020','Virtues of the Quran','quran','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(17,'إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا، وَيَضَعُ بِهِ آخَرِينَ','Verily, Allah elevates nations through this Book (the Quran) and debases others with it.','یقیناً اللہ تعالیٰ اس کتاب (قرآن مجید) کے ذریعے قوموں کو سربلند فرماتا ہے اور اسی کے ذریعے دوسروں کو پست کرتا ہے۔','Umar ibn al-Khattab (RA)','Sahih Muslim 817','Virtues of the Quran','quran','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(18,'تَعَاهَدُوا هَذَا الْقُرْآنَ، فَوَالَّذِي نَفْسِي بِيَدِهِ لَهُوَ أَشَدُّ تَفَصِّيًا مِنَ الإِبِلِ فِي عُقُلِهَا','Keep refreshing your knowledge of this Quran, for by Him in Whose Hand is my soul, it slips away faster than a tethered camel.','اس قرآن کی مسلسل دہرائی کرتے رہا کرو، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، یہ رسی سے بندھے اونٹ سے بھی زیادہ تیزی سے چھوٹتا ہے۔','Abu Musa al-Ashari (RA)','Sahih al-Bukhari 5033','Memorization & Revision of Quran','quran','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(19,'قُلْ هُوَ اللَّهُ أَحَدٌ تَعْدِلُ ثُلُثَ الْقُرْآنِ','Surah Al-Ikhlas (Say: He is Allah, the One) is equivalent to one third of the Quran.','سورۃ الاخلاص (قل ھو اللہ احد) ایک تہائی قرآن کے برابر ہے۔','Abu Said al-Khudri (RA)','Sahih Muslim 811','Virtues of Surah Al-Ikhlas','quran','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(20,'طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ','Seeking knowledge is an obligation upon every Muslim.','علم حاصل کرنا ہر مسلمان پر فرض ہے۔','Anas ibn Malik (RA)','Sunan Ibn Majah 224','The Importance of Knowledge','knowledge','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(21,'مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ، لاَ يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا','Whoever calls to guidance will have a reward similar to that of those who follow him, without their reward being diminished in the least.','جو کسی نیک راہ کی طرف بلائے گا اسے ان سب کا ثواب ملے گا جو اس پر عمل کریں گے، بغیر اس کے کہ ان کے ثواب میں کوئی کمی ہو۔','Abu Hurairah (RA)','Sahih Muslim 2674','Spreading Knowledge & Guidance','knowledge','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(22,'إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ: إِلاَّ مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ','When a human being dies, his deeds end except for three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.','جب انسان مر جاتا ہے تو اس کے اعمال کا سلسلہ بند ہو جاتا ہے سوائے تین چیزوں کے: صدقہ جاریہ، ایسا علم جس سے نفع اٹھایا جائے، یا نیک اولاد جو اس کے لیے دعا کرے۔','Abu Hurairah (RA)','Sahih Muslim 1631','Wills and Continuous Deeds','knowledge','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(23,'الْكَلِمَةُ الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ، فَحَيْثُ وَجَدَهَا فَهُوَ أَحَقُّ بِهَا','A word of wisdom is the lost property of the believer; wherever he finds it, he has the greatest right to it.','حکمت و دانائی کی بات مومن کی گمشدہ میراث ہے، وہ جہاں بھی اسے پائے وہی اس کا سب سے زیادہ حقدار ہے۔','Abu Hurairah (RA)','Jami at-Tirmidhi 2687','Seeking Wisdom','knowledge','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(24,'مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ حُسْنِ الْخُلُقِ','Nothing is heavier upon the scale of a believer on the Day of Resurrection than good character.','قیامت کے دن مومن کے پلڑے میں اچھے اخلاق سے زیادہ وزنی کوئی چیز نہیں ہوگی۔','Abu Darda (RA)','Jami at-Tirmidhi 2002','Righteousness','character','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(25,'لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ','None of you truly believes until he loves for his brother what he loves for himself.','تم میں سے کوئی شخص اُس وقت تک کامل مومن نہیں ہو سکتا جب تک کہ وہ اپنے بھائی کے لیے وہی پسند نہ کرے جو اپنے لیے پسند کرتا ہے۔','Anas ibn Malik (RA)','Sahih al-Bukhari 13','Faith (Iman)','character','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(26,'الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ','A true Muslim is the one from whose tongue and hand other Muslims are safe.','مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں۔','Abdullah ibn Amr (RA)','Sahih al-Bukhari 10','Faith','character','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(27,'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ','Whoever believes in Allah and the Last Day, let him speak good or remain silent.','جو شخص اللہ اور یومِ آخرت پر ایمان رکھتا ہے اسے چاہیے کہ اچھی بات کہے یا خاموش رہے۔','Abu Hurairah (RA)','Sahih al-Bukhari 6018','Speech and Etiquette','character','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(28,'الْبِرُّ حُسْنُ الْخُلُقِ، وَالإِثْمُ مَا حَاكَ فِي صَدْرِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ','Righteousness is good character, and sin is that which wavers in your heart and which you would dislike people to discover.','نیکی حسنِ اخلاق کا نام ہے، اور گناہ وہ ہے جو تیرے دل میں کھٹکے اور تو ناپسند کرے کہ لوگ اس پر مطلع ہوں۔','An-Nawwas ibn Saman (RA)','Sahih Muslim 2553','Righteousness and Piety','character','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(29,'الصَّلاَةُ عَلَى وَقْتِهَا','The best of all deeds is performing prayer at its appointed time.','سب سے افضل عمل وقت پر نماز ادا کرنا ہے۔','Abdullah ibn Masud (RA)','Sahih al-Bukhari 527','Times of the Prayers','prayer','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(30,'الطُّهُورُ شَطْرُ الإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلأُ الْمِيزَانَ','Cleanliness and purification is half of faith, and saying Alhamdulillah fills the scale of good deeds.','پاکیزگی نصف ایمان ہے، اور الحمد للہ کہنا ترازو کو نیکیوں سے بھر دیتا ہے۔','Abu Malik al-Ashari (RA)','Sahih Muslim 223','Purification and Praise','prayer','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(31,'كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ','Two phrases that are light on the tongue, heavy on the scale, and beloved to the Most Merciful: Subhan Allahi wa bihamdihi, Subhan Allahil Azeem.','دو کلمے جو زبان پر ہلکے، ترازو میں بھاری، اور رحمن کو انتہائی محبوب ہیں: سبحان اللہ وبحمدہ، سبحان اللہ العظیم۔','Abu Hurairah (RA)','Sahih al-Bukhari 6406','Remembrance of Allah','prayer','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(32,'أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ','The closest that a servant comes to his Lord is when he is prostrating, so supplicate abundantly.','بندہ اپنے رب کے سب سے زیادہ قریب سجدے کی حالت میں ہوتا ہے، لہٰذا سجدے میں کثرت سے دعا کیا کرو۔','Abu Hurairah (RA)','Sahih Muslim 482','The Prostration','prayer','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(33,'مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ','The similitude of one who remembers his Lord and one who does not remember his Lord is like that of the living and the dead.','اپنے رب کا ذکر کرنے والے اور ذکر نہ کرنے والے کی مثال زندہ اور مردہ جیسی ہے۔','Abu Musa al-Ashari (RA)','Sahih al-Bukhari 6407','Dhikr & Remembrance','prayer','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(34,'مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا','Whoever sends blessings upon me once, Allah will send blessings upon him tenfold.','جو مجھ پر ایک مرتبہ درود بھیجے گا، اللہ تعالیٰ اس پر دس رحمتیں نازل فرمائے گا۔','Abu Hurairah (RA)','Sahih Muslim 408','Blessings upon the Prophet','prayer','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(35,'مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حُزْنٍ وَلاَ أَذًى وَلاَ غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ','No fatigue, illness, anxiety, sorrow, harm, or distress befalls a Muslim, even the prick of a thorn, except that Allah expiates some of his sins by it.','مسلمان کو جو بھی تھکن، بیماری، فکر، غم، تکلیف یا پریشانی پہنچتی ہے، یہاں تک کہ جو کانٹا بھی اسے چبھتا ہے، اللہ تعالیٰ اس کے بدلے اس کے گناہوں کو مٹا دیتا ہے۔','Abu Said & Abu Hurairah (RA)','Sahih al-Bukhari 5641','Patience in Afflictions','patience','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(36,'مَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ، وَمَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْرًا وَأَوْسَعَ مِنَ الصَّبْرِ','Whoever practices patience, Allah will grant him patience; and no one is given a gift better and more comprehensive than patience.','جو صبر کرنے کی کوشش کرے گا اللہ اسے صبر عطا فرمائے گا، اور کسی کو بھی صبر سے بہتر اور زیادہ کشادہ نعمت نہیں دی گئی۔','Abu Said al-Khudri (RA)','Sahih al-Bukhari 1469','Patience and Contentment','patience','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(37,'احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ','Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him in front of you. If you ask, ask of Allah; if you seek help, seek help from Allah.','تم اللہ کے احکام کی حفاظت کرو، اللہ تمہاری حفاظت فرمائے گا۔ تم اللہ کو یاد رکھو، تم اسے اپنے سامنے پاؤ گے۔ جب مانگنا ہو تو اللہ ہی سے مانگو، اور جب مدد طلب کرنی ہو تو اللہ ہی سے مدد چاہو۔','Abdullah ibn Abbas (RA)','Jami at-Tirmidhi 2516','Trust in Allah','patience','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(38,'كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ','Live in this world as though you were a stranger or a traveler passing through.','دنیا میں اس طرح رہو جیسے تم کوئی اجنبی ہو یا راستے کا مسافر۔','Abdullah ibn Umar (RA)','Sahih al-Bukhari 6416','Heart Melting Traditions','patience','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(39,'مَنْ لاَ يَرْحَمُ لاَ يُرْحَمُ','He who does not show mercy will not be shown mercy.','جو رحم نہیں کرتا، اس پر رحم نہیں کیا جاتا۔','Jarir ibn Abdullah (RA)','Sahih al-Bukhari 6013','Mercy Towards People','kindness','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(40,'الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ، ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ','The merciful are shown mercy by the Most Merciful. Show mercy to those on earth, and the One in the heavens will show mercy to you.','رحم کرنے والوں پر رحمن رحم فرماتا ہے۔ تم زمین والوں پر رحم کرو، آسمان والا تم پر رحم فرمائے گا۔','Abdullah ibn Amr (RA)','Jami at-Tirmidhi 1924','Mercy and Compassion','kindness','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(41,'خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي','The best among you are those who are best to their families, and I am the best among you to my family.','تم میں سے بہترین شخص وہ ہے جو اپنے اہل و عیال کے لیے سب سے اچھا ہو، اور میں اپنے گھر والوں کے لیے تم سب سے بہتر ہوں۔','Aisha (RA)','Jami at-Tirmidhi 3895','Treatment of Family','kindness','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(42,'جَاءَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ»','A man came and asked: O Messenger of Allah! Who is most deserving of my best companionship? He replied: \"Your mother.\" The man asked: Then who? He replied: \"Your mother.\" The man asked: Then who? He replied: \"Your mother.\" The man asked: Then who? He replied: \"Then your father.\"','ایک شخص نے عرض کیا: یا رسول اللہ! میرے اچھے سلوک کا سب سے زیادہ حقدار کون ہے؟ آپ ﷺ نے فرمایا: \"تیری ماں۔\" پوچھا: پھر کون؟ فرمایا: \"تیری ماں۔\" پوچھا: پھر کون؟ فرمایا: \"تیری ماں۔\" پوچھا: پھر کون؟ فرمایا: \"پھر تیرا باپ۔\"','Abu Hurairah (RA)','Sahih al-Bukhari 5971','Righteousness Towards Parents','kindness','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(43,'اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ','Protect yourselves from the Hellfire, even by giving half of a date in charity.','جہنم کی آگ سے بچو، خواہ کھجور کا ایک ٹکڑا ہی صدقہ کر کے ہو۔','Adi ibn Hatim (RA)','Sahih al-Bukhari 1417','Charity and Saving from Hell','kindness','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(44,'أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا، وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى','I and the sponsor of an orphan will be in Paradise like this — and he indicated with his index and middle fingers.','میں اور یتیم کی کفالت کرنے والا جنت میں اس طرح ہوں گے — اور آپ ﷺ نے اپنی شہادت کی اور بیچ کی انگلی سے اشارہ فرمایا۔','Sahl ibn Sa\'d (RA)','Sahih al-Bukhari 5304','Caring for Orphans','kindness','Sahih',1,'2026-10-21 05:07:48','2026-10-21 05:07:48'),(45,'السَّاعِي عَلَى الأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ، أَوِ الْقَائِمِ اللَّيْلَ الصَّائِمِ النَّهَارَ','The one who strives on behalf of the widow and the needy is like the warrior in the cause of Allah, or like one who prays all night and fasts all day.','بیواؤں اور مسکینوں کی خبرگیری کرنے والا اللہ کے راستے میں جہاد کرنے والے کی مانند ہے، یا اس شخص کی طرح جو رات بھر نماز پڑھے اور دن بھر روزے رکھے۔','Abu Hurairah (RA)','Sahih al-Bukhari 5353','Helping the Needy','kindness','Sahih',0,'2026-10-21 05:07:48','2026-10-21 05:07:48');
/*!40000 ALTER TABLE `hadiths` ENABLE KEYS */;
