INSERT INTO `site_pages` VALUES (1,'About Bayan AI Quran Teacher','about','<h2>Empowering Quran Learners Globally</h2><p>Bayan AI Quran Teacher combines cutting-edge speech recognition technology with classical Islamic scholarship. Our mission is to make authentic Quranic reading, proper pronunciation (Tajweed), and disciplined memorization (Hifz) accessible to every Muslim and seeker of knowledge around the world.</p><h3>Key Pillars</h3><ul><li><strong>Interactive Quran Reading:</strong> Uthmani script typography accompanied by clear English translations and verse-by-verse recitations from world-renowned Qaris.</li><li><strong>AI Recitation Teacher:</strong> Immediate, discreet acoustic feedback highlighting correctly pronounced words and pointing out missed phrases.</li><li><strong>Spaced-Repetition Hifz:</strong> Proven cognitive scheduling algorithms that ensure you never forget what you have memorized.</li></ul>',1,'2026-10-19 00:28:57','2026-10-19 00:28:57'),(2,'Privacy Policy & Voice Data Governance','privacy-policy','<h2>Privacy & Voice Data Governance</h2><p>At Bayan AI Quran Teacher, safeguarding your privacy and respecting the sanctity of Quranic recitation is central to our ethics.</p><h3>Voice Data Handling</h3><ul><li>Voice analysis is conducted in real-time. Browser speech recognition processes audio through secure client-side APIs.</li><li>Raw voice recordings are never stored permanently or sold to third-party advertising companies.</li><li>You maintain absolute sovereignty over your learning history and may permanently purge your study records from your account settings at any moment.</li></ul>',1,'2026-10-19 00:28:57','2026-10-19 00:28:57'),(3,'Terms of Service','terms-of-service','<h2>Terms of Service</h2><p>Welcome to Bayan AI Quran Teacher. By accessing or utilizing our learning portal, you agree to abide by these Terms of Service.</p><h3>Respectful Usage</h3><p>Users must use the platform respectfully for educational, spiritual, and personal development purposes. The automated voice assessment system provides assistive guidance and is designed to supplement, rather than entirely supplant, traditional one-on-one study with qualified human Quran teachers (Ijaza holders).</p>',1,'2026-10-19 00:28:57','2026-10-19 00:28:57');
/*!40000 ALTER TABLE `site_pages` ENABLE KEYS */;
UNLOCK TABLES;

